package com.bridger.momentum;

import java.util.*;

/** Recorded keystrokes and a compact video title, with no playback instructions. */
public final class ReplayVideoOverlay {
    public static void paint(UiCanvas canvas,int width,int height,ReplayData.Frame pose,String name,double seconds,double duration,ReplayVideoOptions options){
        ReplayData.TickStats stats=pose.stats;
        if(options.inputs){int h=ReplayInputOverlay.height(stats)+(stats==null?0:18);float scale=(float)Math.max(.1,Math.min(BridgeConfig.inputHudScale,Math.min((width-8f)/76,(height-8f)/h)));int x=OverlayPlacement.clamp(BridgeConfig.inputHudX,(int)Math.ceil(76*scale),width),y=OverlayPlacement.clamp(BridgeConfig.inputHudY,(int)Math.ceil(h*scale),height);UiCanvas keys=new ScaledUiCanvas(canvas,x,y,scale);ReplayInputOverlay.paint(keys,0,0,stats);if(stats!=null){keys.rect(0,96,76,14,0xC0080F18);String cps="CPS "+stats.leftCps+" / "+stats.rightCps;keys.text(cps,Math.max(2,(76-keys.width(cps))/2),100,0xFFE8EDF5);}}
        if(options.hotbar)hotbar(canvas,width,height);
        if(options.title){String text=shorten(canvas,name,width-32)+String.format(Locale.US," | %.2f / %.2fs",seconds,duration);float scale=(float)Math.min(1,(width-24.0)/Math.max(1,canvas.width(text)+16));int w=(int)Math.ceil((canvas.width(text)+16)*scale),y=Math.max(0,height-(options.hotbar?54:30));UiCanvas title=new ScaledUiCanvas(canvas,(width-w)/2,y,scale);title.rect(0,0,canvas.width(text)+16,20,0xC0080F18);title.rect(0,0,2,20,0xFF63D3D3);title.text(text,8,6,0xFFF1FFFF);}
        if(options.metrics){List<String> lines=new ArrayList<>();lines.add(String.format(Locale.US,"XYZ %.4f  %.4f  %.4f",pose.x,pose.y,pose.z));if(stats!=null)lines.add(String.format(Locale.US,"Velocity X %.4f Y %.4f Z %.4f",stats.vx,stats.vy,stats.vz));else lines.add("Velocity unavailable in this recording");int w=0;for(String line:lines)w=Math.max(w,canvas.width(line));float scale=(float)Math.max(.1,Math.min(BridgeConfig.replayHudScale,(width-16.0)/(w+16)));int boxW=(int)Math.ceil((w+16)*scale),boxH=(int)Math.ceil(38*scale);int x=OverlayPlacement.clamp(BridgeConfig.replayHudX<0?width-boxW-8:BridgeConfig.replayHudX,boxW,width),y=OverlayPlacement.clamp(BridgeConfig.replayHudY<0?8:BridgeConfig.replayHudY,boxH,height);UiCanvas metrics=new ScaledUiCanvas(canvas,x,y,scale);metrics.rect(0,0,w+16,38,0xC0080F18);for(int i=0;i<lines.size();i++)metrics.text(lines.get(i),8,7+i*14,0xFFE8EDF5);}
    }
    public static float hotbarScale(int width){return (float)Math.min(1,Math.max(.1,(width-8.0)/182));}
    public static void hotbar(UiCanvas canvas,int width,int height){float scale=hotbarScale(width);int w=(int)Math.ceil(182*scale),y=height-(int)Math.ceil(24*scale);UiCanvas bar=new ScaledUiCanvas(canvas,(width-w)/2,y,scale);bar.rect(0,0,182,22,0xE010141A);for(int i=0;i<9;i++){bar.rect(2+i*20,2,18,18,0xFF303844);bar.rect(3+i*20,3,16,16,0xE0080C12);}bar.rect(0,0,22,2,0xFFF1FFFF);bar.rect(0,20,22,2,0xFFF1FFFF);bar.rect(0,2,2,18,0xFFF1FFFF);bar.rect(20,2,2,18,0xFFF1FFFF);}
    public static void ending(UiCanvas canvas,int width,int height,String time){String plain="Time: "+time;float scale=(float)Math.min(4,(width*.82)/Math.max(1,canvas.width(plain)));int w=(int)Math.ceil(canvas.width(plain)*scale),x=(width-w)/2,y=(int)(height*.27);canvas.textScaled(plain,x+Math.max(1,(int)scale),y+Math.max(1,(int)scale),0xAA000000,scale);canvas.textScaled("\u00a7aTime: \u00a7e"+time,x,y,0xFFFFFF,scale);}
    private static String shorten(UiCanvas canvas,String text,int max){while(text.length()>1&&canvas.width(text)>Math.max(20,max))text=text.substring(0,text.offsetByCodePoints(text.length(),-1));return text;}
    public static void progress(UiCanvas canvas,int width,int height,String label,int percent){int w=Math.max(24,Math.min(420,width-24)),x=(width-w)/2,y=Math.max(0,height-96);canvas.rect(x,y,w,27,0xE0101722);canvas.rect(x,y+25,w,2,0xFF304054);canvas.rect(x,y+25,(w*Math.max(0,Math.min(100,percent)))/100,2,0xFF63D3D3);String text=shorten(canvas,label,w-16);canvas.text(text,x+(w-canvas.width(text))/2,y+9,0xFFE8EDF5);}
}
